CREATE TABLE IF NOT EXISTS "users" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Public handle shown on leaderboards. Unique and compared case-insensitively.
	"username" VARCHAR(30) NOT NULL UNIQUE,
	-- Login address. Null for accounts created anonymously on a device and never converted.
	"email" VARCHAR(320) UNIQUE,
	-- Optional friendly name; falls back to the username in the UI.
	"display_name" VARCHAR(80),
	-- BCP-47 tag for the interface, e.g. en or pt-BR. Independent of the languages being learned.
	"ui_language_code" CHAR(5) NOT NULL DEFAULT 'en',
	-- IANA zone. The streak is a local-calendar fact, so the day boundary has to be the learner's, not UTC.
	"timezone" VARCHAR(64) NOT NULL DEFAULT 'UTC',
	-- Course the app opens on. Null until the first course is picked; denormalised so the home screen is one read.
	"active_course_id" BIGINT,
	-- Set by an active subscription. Cached here so lesson start does not join to billing on every tap.
	"has_unlimited_hearts" BOOLEAN NOT NULL DEFAULT false,
	-- Signup time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "users" IS 'A learner. Everything gamified — streak, hearts, league standing — hangs off this row rather than off a course, because those are properties of the person across all the languages they study.';
COMMENT ON COLUMN "users"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "users"."username" IS 'Public handle shown on leaderboards. Unique and compared case-insensitively.';
COMMENT ON COLUMN "users"."email" IS 'Login address. Null for accounts created anonymously on a device and never converted.';
COMMENT ON COLUMN "users"."display_name" IS 'Optional friendly name; falls back to the username in the UI.';
COMMENT ON COLUMN "users"."ui_language_code" IS 'BCP-47 tag for the interface, e.g. en or pt-BR. Independent of the languages being learned.';
COMMENT ON COLUMN "users"."timezone" IS 'IANA zone. The streak is a local-calendar fact, so the day boundary has to be the learner''s, not UTC.';
COMMENT ON COLUMN "users"."active_course_id" IS 'Course the app opens on. Null until the first course is picked; denormalised so the home screen is one read.';
COMMENT ON COLUMN "users"."has_unlimited_hearts" IS 'Set by an active subscription. Cached here so lesson start does not join to billing on every tap.';
COMMENT ON COLUMN "users"."created_at" IS 'Signup time.';

CREATE INDEX "idx_users_active_course"
ON "users" ("active_course_id");

CREATE TABLE IF NOT EXISTS "languages" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- ISO 639 code, e.g. es, ga, haw. Stable identifier used in URLs.
	"code" VARCHAR(12) NOT NULL UNIQUE,
	-- English name, used for admin tooling and fallback rendering.
	"name_en" VARCHAR(80) NOT NULL,
	-- Endonym shown in the language picker, e.g. Español.
	"native_name" VARCHAR(80) NOT NULL,
	-- ltr | rtl. Drives layout for Arabic and Hebrew courses.
	"writing_direction" VARCHAR(3) NOT NULL DEFAULT 'ltr',
	-- Whether answer grading should tolerate missing accents. A grading rule, not decoration.
	"has_diacritics" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "languages" IS 'A language, not a course. Kept separate because the same language appears on both sides of many courses and its rendering rules must not be duplicated per course.';
COMMENT ON COLUMN "languages"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "languages"."code" IS 'ISO 639 code, e.g. es, ga, haw. Stable identifier used in URLs.';
COMMENT ON COLUMN "languages"."name_en" IS 'English name, used for admin tooling and fallback rendering.';
COMMENT ON COLUMN "languages"."native_name" IS 'Endonym shown in the language picker, e.g. Español.';
COMMENT ON COLUMN "languages"."writing_direction" IS 'ltr | rtl. Drives layout for Arabic and Hebrew courses.';
COMMENT ON COLUMN "languages"."has_diacritics" IS 'Whether answer grading should tolerate missing accents. A grading rule, not decoration.';

CREATE TABLE IF NOT EXISTS "courses" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Language the learner already knows — the language instructions are written in.
	"from_language_id" BIGINT NOT NULL,
	-- Language being taught.
	"to_language_id" BIGINT NOT NULL,
	-- URL segment, e.g. es-from-en.
	"slug" VARCHAR(40) NOT NULL UNIQUE,
	-- alpha | beta | live | retired. Courses ship incrementally and learners are told which stage they are on.
	"status" VARCHAR(20) NOT NULL DEFAULT 'beta',
	-- Denormalised tree size, so the course picker can show progress without walking skills.
	"skill_count" INTEGER NOT NULL DEFAULT 0,
	-- Public launch date. Null while the course is still in incubation.
	"released_at" DATE,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "courses" IS 'A directional course: Spanish-from-English is a different row from English-from-Spanish. Direction is the whole point — the content, audio and grading rules differ even though the language pair is the same.';
COMMENT ON COLUMN "courses"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "courses"."from_language_id" IS 'Language the learner already knows — the language instructions are written in.';
COMMENT ON COLUMN "courses"."to_language_id" IS 'Language being taught.';
COMMENT ON COLUMN "courses"."slug" IS 'URL segment, e.g. es-from-en.';
COMMENT ON COLUMN "courses"."status" IS 'alpha | beta | live | retired. Courses ship incrementally and learners are told which stage they are on.';
COMMENT ON COLUMN "courses"."skill_count" IS 'Denormalised tree size, so the course picker can show progress without walking skills.';
COMMENT ON COLUMN "courses"."released_at" IS 'Public launch date. Null while the course is still in incubation.';

CREATE UNIQUE INDEX "uq_courses_direction"
ON "courses" ("from_language_id", "to_language_id");

CREATE TABLE IF NOT EXISTS "user_courses" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Learner.
	"user_id" BIGINT NOT NULL,
	-- Course being studied.
	"course_id" BIGINT NOT NULL,
	-- When the learner added this course. Ordering for the course switcher.
	"started_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Local date of the most recent session in this course, used to nudge dormant courses.
	"last_practised_on" DATE,
	-- Lifetime XP in this course. Per-course rather than per-user because leaderboards and course badges are scoped to one language.
	"total_xp" INTEGER NOT NULL DEFAULT 0,
	-- Self-set target. The streak is satisfied when the day's XP reaches it.
	"daily_goal_xp" INTEGER NOT NULL DEFAULT 20,
	-- Section the placement test dropped the learner into. Null when they started from zero.
	"placement_level" SMALLINT,
	-- Mistake budget. Nullable semantics avoided: unlimited hearts is a flag on users, not a null here.
	"hearts_remaining" SMALLINT NOT NULL DEFAULT 5,
	-- When the next heart regenerates. Null when hearts are full — recomputed on read rather than by a background job.
	"hearts_refill_at" TIMESTAMPTZ,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "user_courses" IS 'One learner''s relationship with one course. Hearts live here and not on the user so a bad session in German does not lock the learner out of French.';
COMMENT ON COLUMN "user_courses"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "user_courses"."user_id" IS 'Learner.';
COMMENT ON COLUMN "user_courses"."course_id" IS 'Course being studied.';
COMMENT ON COLUMN "user_courses"."started_at" IS 'When the learner added this course. Ordering for the course switcher.';
COMMENT ON COLUMN "user_courses"."last_practised_on" IS 'Local date of the most recent session in this course, used to nudge dormant courses.';
COMMENT ON COLUMN "user_courses"."total_xp" IS 'Lifetime XP in this course. Per-course rather than per-user because leaderboards and course badges are scoped to one language.';
COMMENT ON COLUMN "user_courses"."daily_goal_xp" IS 'Self-set target. The streak is satisfied when the day''s XP reaches it.';
COMMENT ON COLUMN "user_courses"."placement_level" IS 'Section the placement test dropped the learner into. Null when they started from zero.';
COMMENT ON COLUMN "user_courses"."hearts_remaining" IS 'Mistake budget. Nullable semantics avoided: unlimited hearts is a flag on users, not a null here.';
COMMENT ON COLUMN "user_courses"."hearts_refill_at" IS 'When the next heart regenerates. Null when hearts are full — recomputed on read rather than by a background job.';

CREATE UNIQUE INDEX "uq_user_courses_user_course"
ON "user_courses" ("user_id", "course_id");

CREATE TABLE IF NOT EXISTS "skills" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Course this skill belongs to.
	"course_id" BIGINT NOT NULL,
	-- Enclosing unit. Null for a top-level unit, which is what makes this table a tree rather than a flat list.
	"parent_skill_id" BIGINT,
	-- Stable identifier used in deep links, e.g. present-tense-1.
	"slug" VARCHAR(60) NOT NULL,
	-- Displayed name of the unit or skill.
	"title" VARCHAR(120) NOT NULL,
	-- Position among siblings. Integers with gaps so a skill can be inserted mid-tree without renumbering the course.
	"tree_ordinal" INTEGER NOT NULL,
	-- Skill that gates this one. Null for the course entry point. A single edge, not a set, because the tree is deliberately near-linear.
	"unlock_after_skill_id" BIGINT,
	-- Crown level the gating skill must reach. Raising it is how a course forces revision before new material.
	"unlock_at_crown_level" SMALLINT NOT NULL DEFAULT 1,
	-- How many times the skill can be levelled up. Per skill because short skills cap lower.
	"max_crown_level" SMALLINT NOT NULL DEFAULT 5,
	-- True for optional or paid skills; excluded from course completion percentages.
	"is_bonus" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "skills" IS 'A node in the skill tree. Unlocking is stored as an edge plus a required crown level rather than as computed state, so changing the course layout never invalidates what learners have already earned.';
COMMENT ON COLUMN "skills"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "skills"."course_id" IS 'Course this skill belongs to.';
COMMENT ON COLUMN "skills"."parent_skill_id" IS 'Enclosing unit. Null for a top-level unit, which is what makes this table a tree rather than a flat list.';
COMMENT ON COLUMN "skills"."slug" IS 'Stable identifier used in deep links, e.g. present-tense-1.';
COMMENT ON COLUMN "skills"."title" IS 'Displayed name of the unit or skill.';
COMMENT ON COLUMN "skills"."tree_ordinal" IS 'Position among siblings. Integers with gaps so a skill can be inserted mid-tree without renumbering the course.';
COMMENT ON COLUMN "skills"."unlock_after_skill_id" IS 'Skill that gates this one. Null for the course entry point. A single edge, not a set, because the tree is deliberately near-linear.';
COMMENT ON COLUMN "skills"."unlock_at_crown_level" IS 'Crown level the gating skill must reach. Raising it is how a course forces revision before new material.';
COMMENT ON COLUMN "skills"."max_crown_level" IS 'How many times the skill can be levelled up. Per skill because short skills cap lower.';
COMMENT ON COLUMN "skills"."is_bonus" IS 'True for optional or paid skills; excluded from course completion percentages.';

CREATE UNIQUE INDEX "uq_skills_course_slug"
ON "skills" ("course_id", "slug");
CREATE INDEX "idx_skills_tree_order"
ON "skills" ("course_id", "parent_skill_id", "tree_ordinal");

CREATE TABLE IF NOT EXISTS "lessons" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Skill this lesson belongs to.
	"skill_id" BIGINT NOT NULL,
	-- Position within the skill; also the order lessons unlock in.
	"lesson_ordinal" INTEGER NOT NULL,
	-- Crown level from which this lesson is served. Higher levels of the same skill draw harder lessons rather than new skills.
	"min_crown_level" SMALLINT NOT NULL DEFAULT 0,
	-- How many exercise items a session serves from this lesson's pool.
	"item_count" SMALLINT NOT NULL DEFAULT 15,
	-- XP granted on completion. Stored per lesson so events can boost specific content.
	"xp_reward" INTEGER NOT NULL DEFAULT 10,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "lessons" IS 'A single session''s worth of practice inside a skill. Lessons are pools, not fixed scripts: the session picks item_count items, which is what lets the same lesson feel different on a second pass.';
COMMENT ON COLUMN "lessons"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "lessons"."skill_id" IS 'Skill this lesson belongs to.';
COMMENT ON COLUMN "lessons"."lesson_ordinal" IS 'Position within the skill; also the order lessons unlock in.';
COMMENT ON COLUMN "lessons"."min_crown_level" IS 'Crown level from which this lesson is served. Higher levels of the same skill draw harder lessons rather than new skills.';
COMMENT ON COLUMN "lessons"."item_count" IS 'How many exercise items a session serves from this lesson''s pool.';
COMMENT ON COLUMN "lessons"."xp_reward" IS 'XP granted on completion. Stored per lesson so events can boost specific content.';

CREATE UNIQUE INDEX "uq_lessons_skill_ordinal"
ON "lessons" ("skill_id", "lesson_ordinal");

CREATE TABLE IF NOT EXISTS "lexemes" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Course whose vocabulary this belongs to. Scoped per course because the same word is taught differently by direction.
	"course_id" BIGINT NOT NULL,
	-- The word or phrase as the learner sees it.
	"surface_form" VARCHAR(120) NOT NULL,
	-- Dictionary form. Two conjugations of the same verb share a lemma but are separate lexemes with separate schedules.
	"lemma" VARCHAR(120) NOT NULL,
	-- noun | verb | adjective | adverb | phrase | other. Used to group the word list and to pick exercise templates.
	"part_of_speech" VARCHAR(24),
	-- Short translation into the course's from-language.
	"gloss" VARCHAR(240) NOT NULL,
	-- Recorded pronunciation. Null where no recording exists yet, which is common in beta courses.
	"audio_url" VARCHAR(500),
	-- Corpus frequency rank; lower is more common. Seeds the first review interval before any learner data exists.
	"difficulty_rank" INTEGER,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "lexemes" IS 'The unit of vocabulary knowledge. It is separate from exercise items because a learner knows a word, not a sentence — the whole review schedule is keyed on this table.';
COMMENT ON COLUMN "lexemes"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "lexemes"."course_id" IS 'Course whose vocabulary this belongs to. Scoped per course because the same word is taught differently by direction.';
COMMENT ON COLUMN "lexemes"."surface_form" IS 'The word or phrase as the learner sees it.';
COMMENT ON COLUMN "lexemes"."lemma" IS 'Dictionary form. Two conjugations of the same verb share a lemma but are separate lexemes with separate schedules.';
COMMENT ON COLUMN "lexemes"."part_of_speech" IS 'noun | verb | adjective | adverb | phrase | other. Used to group the word list and to pick exercise templates.';
COMMENT ON COLUMN "lexemes"."gloss" IS 'Short translation into the course''s from-language.';
COMMENT ON COLUMN "lexemes"."audio_url" IS 'Recorded pronunciation. Null where no recording exists yet, which is common in beta courses.';
COMMENT ON COLUMN "lexemes"."difficulty_rank" IS 'Corpus frequency rank; lower is more common. Seeds the first review interval before any learner data exists.';

CREATE UNIQUE INDEX "uq_lexemes_course_surface"
ON "lexemes" ("course_id", "surface_form");
CREATE INDEX "idx_lexemes_course_lemma"
ON "lexemes" ("course_id", "lemma");

CREATE TABLE IF NOT EXISTS "exercise_items" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Lesson pool this item belongs to.
	"lesson_id" BIGINT NOT NULL,
	-- Word this item primarily tests. Null for grammar drills that are not about one word.
	"lexeme_id" BIGINT,
	-- translate | select_image | listen_type | speak | match_pairs | fill_blank.
	"exercise_type" VARCHAR(24) NOT NULL,
	-- What the learner is shown or hears.
	"prompt" TEXT NOT NULL,
	-- Array of accepted responses with per-answer tolerance flags. JSON because the shape differs per exercise_type and grading is done by the client-side checker.
	"accepted_answers" JSONB NOT NULL,
	-- Wrong options for multiple-choice and matching items. Null for free-text items, which have no options.
	"distractors" JSONB,
	-- Clip for listening items. Null for reading-only exercises.
	"audio_url" VARCHAR(500),
	-- 1-5. Higher-crown sessions weight the pool towards harder items.
	"difficulty" SMALLINT NOT NULL DEFAULT 1,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "exercise_items" IS 'One question. Items reference a lexeme so that answering one updates that word''s review schedule — the exercise is the delivery mechanism, the lexeme is what is being remembered.';
COMMENT ON COLUMN "exercise_items"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "exercise_items"."lesson_id" IS 'Lesson pool this item belongs to.';
COMMENT ON COLUMN "exercise_items"."lexeme_id" IS 'Word this item primarily tests. Null for grammar drills that are not about one word.';
COMMENT ON COLUMN "exercise_items"."exercise_type" IS 'translate | select_image | listen_type | speak | match_pairs | fill_blank.';
COMMENT ON COLUMN "exercise_items"."prompt" IS 'What the learner is shown or hears.';
COMMENT ON COLUMN "exercise_items"."accepted_answers" IS 'Array of accepted responses with per-answer tolerance flags. JSON because the shape differs per exercise_type and grading is done by the client-side checker.';
COMMENT ON COLUMN "exercise_items"."distractors" IS 'Wrong options for multiple-choice and matching items. Null for free-text items, which have no options.';
COMMENT ON COLUMN "exercise_items"."audio_url" IS 'Clip for listening items. Null for reading-only exercises.';
COMMENT ON COLUMN "exercise_items"."difficulty" IS '1-5. Higher-crown sessions weight the pool towards harder items.';

CREATE INDEX "idx_exercise_items_lesson_difficulty"
ON "exercise_items" ("lesson_id", "difficulty");
CREATE INDEX "idx_exercise_items_lexeme"
ON "exercise_items" ("lexeme_id");

CREATE TABLE IF NOT EXISTS "user_skill_progress" (
	-- Learner. Half of the composite primary key.
	"user_id" BIGINT,
	-- Skill. The other half; no surrogate id because there is exactly one row per pair.
	"skill_id" BIGINT,
	-- 0 means unlocked but untouched. Reaching max_crown_level gilds the skill.
	"crown_level" SMALLINT NOT NULL DEFAULT 0,
	-- Progress towards the next crown. Resets to zero each time a crown is earned.
	"lessons_completed_at_level" SMALLINT NOT NULL DEFAULT 0,
	-- Materialised gate result. Stored rather than derived so the tree screen does not recursively evaluate prerequisites on every render.
	"is_unlocked" BOOLEAN NOT NULL DEFAULT false,
	-- Decayed freshness used to colour the skill amber when it needs practice. A display rollup of the underlying lexeme schedules.
	"strength_percent" SMALLINT NOT NULL DEFAULT 100,
	-- Most recent session on this skill; the input to strength decay.
	"last_practised_at" TIMESTAMPTZ,
	PRIMARY KEY("user_id", "skill_id")
);

COMMENT ON TABLE "user_skill_progress" IS 'One row per learner per skill. Crown level lives here rather than on the skill because it is the only durable measure of how well the learner knows that material.';
COMMENT ON COLUMN "user_skill_progress"."user_id" IS 'Learner. Half of the composite primary key.';
COMMENT ON COLUMN "user_skill_progress"."skill_id" IS 'Skill. The other half; no surrogate id because there is exactly one row per pair.';
COMMENT ON COLUMN "user_skill_progress"."crown_level" IS '0 means unlocked but untouched. Reaching max_crown_level gilds the skill.';
COMMENT ON COLUMN "user_skill_progress"."lessons_completed_at_level" IS 'Progress towards the next crown. Resets to zero each time a crown is earned.';
COMMENT ON COLUMN "user_skill_progress"."is_unlocked" IS 'Materialised gate result. Stored rather than derived so the tree screen does not recursively evaluate prerequisites on every render.';
COMMENT ON COLUMN "user_skill_progress"."strength_percent" IS 'Decayed freshness used to colour the skill amber when it needs practice. A display rollup of the underlying lexeme schedules.';
COMMENT ON COLUMN "user_skill_progress"."last_practised_at" IS 'Most recent session on this skill; the input to strength decay.';

CREATE INDEX "idx_user_skill_progress_skill"
ON "user_skill_progress" ("skill_id");

CREATE TABLE IF NOT EXISTS "user_lexeme_reviews" (
	-- Learner. Half of the composite primary key.
	"user_id" BIGINT,
	-- Word being tracked. The other half of the key — one schedule per learner per word.
	"lexeme_id" BIGINT,
	-- When the word was introduced. Kept for cohort analysis of retention curves.
	"first_learned_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Timestamp of the last answer, and the origin the next interval is measured from.
	"last_reviewed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When the word should be practised again. Materialised rather than computed on read, because the hot query is "what is due now" across millions of rows.
	"due_at" TIMESTAMPTZ NOT NULL,
	-- Hours after which recall probability is estimated at 0.5. The model's state variable — a correct answer lengthens it, a lapse collapses it.
	"half_life_hours" NUMERIC(10,3) NOT NULL DEFAULT 24,
	-- Per-learner multiplier on interval growth. Two people can know the same word at very different rates.
	"ease_factor" NUMERIC(4,3) NOT NULL DEFAULT 2.5,
	-- Consecutive correct reviews. Drives the early ramp before the half-life estimate has enough data.
	"repetitions" INTEGER NOT NULL DEFAULT 0,
	-- Times the word was forgotten after being learned. A high count is what marks a word as a "hard" word.
	"lapses" INTEGER NOT NULL DEFAULT 0,
	-- All-time answer count, correct or not; the denominator for the word's accuracy.
	"total_reviews" INTEGER NOT NULL DEFAULT 0,
	-- True when the word is considered permanently known and dropped from the due queue. Prevents an ever-growing backlog of trivial items.
	"is_retired" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("user_id", "lexeme_id")
);

COMMENT ON TABLE "user_lexeme_reviews" IS 'The spaced-repetition schedule, and the centre of the whole design. Every practice session is a single indexed read of this table ordered by due_at, so the cost of picking what to teach next does not grow with how much the learner knows.';
COMMENT ON COLUMN "user_lexeme_reviews"."user_id" IS 'Learner. Half of the composite primary key.';
COMMENT ON COLUMN "user_lexeme_reviews"."lexeme_id" IS 'Word being tracked. The other half of the key — one schedule per learner per word.';
COMMENT ON COLUMN "user_lexeme_reviews"."first_learned_at" IS 'When the word was introduced. Kept for cohort analysis of retention curves.';
COMMENT ON COLUMN "user_lexeme_reviews"."last_reviewed_at" IS 'Timestamp of the last answer, and the origin the next interval is measured from.';
COMMENT ON COLUMN "user_lexeme_reviews"."due_at" IS 'When the word should be practised again. Materialised rather than computed on read, because the hot query is "what is due now" across millions of rows.';
COMMENT ON COLUMN "user_lexeme_reviews"."half_life_hours" IS 'Hours after which recall probability is estimated at 0.5. The model''s state variable — a correct answer lengthens it, a lapse collapses it.';
COMMENT ON COLUMN "user_lexeme_reviews"."ease_factor" IS 'Per-learner multiplier on interval growth. Two people can know the same word at very different rates.';
COMMENT ON COLUMN "user_lexeme_reviews"."repetitions" IS 'Consecutive correct reviews. Drives the early ramp before the half-life estimate has enough data.';
COMMENT ON COLUMN "user_lexeme_reviews"."lapses" IS 'Times the word was forgotten after being learned. A high count is what marks a word as a "hard" word.';
COMMENT ON COLUMN "user_lexeme_reviews"."total_reviews" IS 'All-time answer count, correct or not; the denominator for the word''s accuracy.';
COMMENT ON COLUMN "user_lexeme_reviews"."is_retired" IS 'True when the word is considered permanently known and dropped from the due queue. Prevents an ever-growing backlog of trivial items.';

CREATE INDEX "idx_lexeme_reviews_user_due"
ON "user_lexeme_reviews" ("user_id", "due_at");
CREATE INDEX "idx_lexeme_reviews_queue"
ON "user_lexeme_reviews" ("user_id", "is_retired", "due_at");
CREATE INDEX "idx_lexeme_reviews_lexeme"
ON "user_lexeme_reviews" ("lexeme_id");

CREATE TABLE IF NOT EXISTS "daily_activity" (
	-- Learner. Half of the composite primary key.
	"user_id" BIGINT,
	-- Local calendar date in the user's timezone. The other half of the key, which is what makes the streak a simple count of consecutive rows.
	"activity_date" DATE,
	-- XP on the day, summed across every course.
	"xp_earned" INTEGER NOT NULL DEFAULT 0,
	-- Sessions finished. Separate from XP because boosts make XP a poor proxy for effort.
	"lessons_completed" SMALLINT NOT NULL DEFAULT 0,
	-- Whether the day's XP reached the daily goal. Frozen once written so a later goal change cannot rewrite streak history.
	"goal_met" BOOLEAN NOT NULL DEFAULT false,
	-- True when a streak freeze was consumed to keep the streak alive on a day with no activity.
	"freeze_used" BOOLEAN NOT NULL DEFAULT false,
	-- Streak length as of the end of this day. Snapshotted so the streak can be displayed and audited without scanning backwards.
	"streak_length_after" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("user_id", "activity_date")
);

COMMENT ON TABLE "daily_activity" IS 'One row per learner per local day, written only on days something happened or a freeze was spent. Storing the resulting streak length on the row is what makes "your streak broke on the 14th" answerable months later.';
COMMENT ON COLUMN "daily_activity"."user_id" IS 'Learner. Half of the composite primary key.';
COMMENT ON COLUMN "daily_activity"."activity_date" IS 'Local calendar date in the user''s timezone. The other half of the key, which is what makes the streak a simple count of consecutive rows.';
COMMENT ON COLUMN "daily_activity"."xp_earned" IS 'XP on the day, summed across every course.';
COMMENT ON COLUMN "daily_activity"."lessons_completed" IS 'Sessions finished. Separate from XP because boosts make XP a poor proxy for effort.';
COMMENT ON COLUMN "daily_activity"."goal_met" IS 'Whether the day''s XP reached the daily goal. Frozen once written so a later goal change cannot rewrite streak history.';
COMMENT ON COLUMN "daily_activity"."freeze_used" IS 'True when a streak freeze was consumed to keep the streak alive on a day with no activity.';
COMMENT ON COLUMN "daily_activity"."streak_length_after" IS 'Streak length as of the end of this day. Snapshotted so the streak can be displayed and audited without scanning backwards.';

CREATE INDEX "idx_daily_activity_user_date"
ON "daily_activity" ("user_id", "activity_date");

CREATE TABLE IF NOT EXISTS "league_cohorts" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- bronze | silver | gold | sapphire | ruby | emerald | amethyst | pearl | obsidian | diamond.
	"tier" VARCHAR(20) NOT NULL,
	-- Monday the contest opens, in UTC. One cohort belongs to exactly one week.
	"week_starts_on" DATE NOT NULL,
	-- Cut-off for scoring. Stored as an instant because promotion runs once globally, not per timezone.
	"week_ends_at" TIMESTAMPTZ NOT NULL,
	-- Maximum members. Cohorts are small on purpose so mid-table learners still see movement.
	"capacity" SMALLINT NOT NULL DEFAULT 30,
	-- Top N promoted to the next tier at the cut-off.
	"promote_count" SMALLINT NOT NULL DEFAULT 7,
	-- Bottom N demoted. Stored per cohort so the rules can be tuned for a week without rewriting history.
	"demote_count" SMALLINT NOT NULL DEFAULT 5,
	-- True once promotions have been applied. Makes settlement idempotent if the job is re-run.
	"is_settled" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "league_cohorts" IS 'One weekly contest bracket of about thirty learners. Making the cohort a row rather than a computed grouping is what lets the promotion rules be a historical fact rather than whatever the code does today.';
COMMENT ON COLUMN "league_cohorts"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "league_cohorts"."tier" IS 'bronze | silver | gold | sapphire | ruby | emerald | amethyst | pearl | obsidian | diamond.';
COMMENT ON COLUMN "league_cohorts"."week_starts_on" IS 'Monday the contest opens, in UTC. One cohort belongs to exactly one week.';
COMMENT ON COLUMN "league_cohorts"."week_ends_at" IS 'Cut-off for scoring. Stored as an instant because promotion runs once globally, not per timezone.';
COMMENT ON COLUMN "league_cohorts"."capacity" IS 'Maximum members. Cohorts are small on purpose so mid-table learners still see movement.';
COMMENT ON COLUMN "league_cohorts"."promote_count" IS 'Top N promoted to the next tier at the cut-off.';
COMMENT ON COLUMN "league_cohorts"."demote_count" IS 'Bottom N demoted. Stored per cohort so the rules can be tuned for a week without rewriting history.';
COMMENT ON COLUMN "league_cohorts"."is_settled" IS 'True once promotions have been applied. Makes settlement idempotent if the job is re-run.';

CREATE INDEX "idx_league_cohorts_tier_week"
ON "league_cohorts" ("tier", "week_starts_on");

CREATE TABLE IF NOT EXISTS "leaderboard_entries" (
	-- Cohort the learner is competing in. Half of the composite primary key.
	"cohort_id" BIGINT,
	-- Competitor. The other half — one entry per learner per cohort.
	"user_id" BIGINT,
	-- Score, incremented as sessions complete. The only column written during the week.
	"xp_this_week" INTEGER NOT NULL DEFAULT 0,
	-- Position at settlement. Null until the cohort is settled, which is also how unsettled weeks are found.
	"final_rank" SMALLINT,
	-- promoted | demoted | stayed. Null until settlement; written once and never recomputed.
	"outcome" VARCHAR(12),
	-- Placement time, used as the tie-break so an earlier joiner wins an equal-XP tie.
	"joined_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("cohort_id", "user_id")
);

COMMENT ON TABLE "leaderboard_entries" IS 'A learner''s standing in one weekly cohort. XP is denormalised here rather than summed from daily_activity because the leaderboard is read constantly and only counts XP earned after placement.';
COMMENT ON COLUMN "leaderboard_entries"."cohort_id" IS 'Cohort the learner is competing in. Half of the composite primary key.';
COMMENT ON COLUMN "leaderboard_entries"."user_id" IS 'Competitor. The other half — one entry per learner per cohort.';
COMMENT ON COLUMN "leaderboard_entries"."xp_this_week" IS 'Score, incremented as sessions complete. The only column written during the week.';
COMMENT ON COLUMN "leaderboard_entries"."final_rank" IS 'Position at settlement. Null until the cohort is settled, which is also how unsettled weeks are found.';
COMMENT ON COLUMN "leaderboard_entries"."outcome" IS 'promoted | demoted | stayed. Null until settlement; written once and never recomputed.';
COMMENT ON COLUMN "leaderboard_entries"."joined_at" IS 'Placement time, used as the tie-break so an earlier joiner wins an equal-XP tie.';

CREATE INDEX "idx_leaderboard_cohort_score"
ON "leaderboard_entries" ("cohort_id", "xp_this_week");
CREATE INDEX "idx_leaderboard_user"
ON "leaderboard_entries" ("user_id", "cohort_id");

